create table if not exists public.rt_matching_sets (id text primary key, content jsonb not null, updated_at timestamptz not null default now());
alter table public.rt_matching_sets enable row level security;
grant select on public.rt_matching_sets to anon,authenticated;
create policy rt_matching_public_read on public.rt_matching_sets for select to anon,authenticated using (true);
insert into public.rt_matching_sets(id,content) values ('2559-1-picture-match','{"id": "2559-1-picture-match", "instruction": "อ่านคำ แล้วแตะภาพที่สัมพันธ์กัน", "items": [{"id": "2559-1-c-1", "prompt": "กระโปรง", "answer": "3"}, {"id": "2559-1-c-2", "prompt": "แตงโม", "answer": "6"}, {"id": "2559-1-c-3", "prompt": "ทะเล", "answer": "5"}, {"id": "2559-1-c-4", "prompt": "นาฬิกา", "answer": "1"}, {"id": "2559-1-c-5", "prompt": "เลี้ยงแพะ", "answer": "4"}, {"id": "2559-1-c-6", "prompt": "กระดุมเสื้อ", "answer": "10"}, {"id": "2559-1-c-7", "prompt": "ยืนตรง", "answer": "8"}, {"id": "2559-1-c-8", "prompt": "บันได", "answer": "9"}, {"id": "2559-1-c-9", "prompt": "ลูกโป่ง", "answer": "12"}, {"id": "2559-1-c-10", "prompt": "ผูกเชือก", "answer": "2"}], "choices": [{"id": "1", "label": "นาฬิกา", "image": "data:image/webp;base64,"}, {"id": "2", "label": "ผูกเชือก", "image": "data:image/webp;base64,"}, {"id": "3", "label": "กระโปรง", "image": "data:image/webp;base64,"}, {"id": "4", "label": "เลี้ยงแพะ", "image": "data:image/webp;base64,"}, {"id": "5", "label": "ทะเล", "image": "data:image/webp;base64,"}, {"id": "6", "label": "แตงโม", "image": "data:image/webp;base64,"}, {"id": "7", "label": "เลี้ยงช้าง", "image": "data:image/webp;base64,"}, {"id": "8", "label": "ยืนตรง", "image": "data:image/webp;base64,"}, {"id": "9", "label": "บันได", "image": "data:image/webp;base64,"}, {"id": "10", "label": "กระดุมเสื้อ", "image": "data:image/webp;base64,"}, {"id": "11", "label": "ม้า", "image": "data:image/webp;base64,"}, {"id": "12", "label": "ลูกโป่ง", "image": "data:image/webp;base64,"}]}'::jsonb) on conflict(id) do update set content=excluded.content,updated_at=now();
